//! A source-record-bound finite conditional FirePot creation/first callback.
use super::{native_appearance_inspection::Binding,native_resources::{NativeStaticAssets,NativeAssetPlan,NativeEffectRecord},native_action_inspection::NativeActionSnapshot,world_map::{WorldCell,ViewProjection,PixelPoint},world_depth::NativeDrawCell,world_roofs::Shade,world_raster::{Raster,PreparedTile,Blend},compositor::Canvas};
use anyhow::{Result,ensure,Context};use std::{collections::BTreeMap,sync::{Arc,atomic::{AtomicBool,Ordering}}};
pub(crate) struct CreateInputs{pub loader_branch_reached:Option<bool>,pub runtime_id_base:Option<u32>,pub catalog_global_offset:Option<u32>,pub player_object_global:Option<u32>,pub existing_actor_absent:Option<bool>,pub allocation_succeeded:Option<bool>,pub render_player_pointer_equal:Option<bool>,pub initial_queue_count:Option<usize>,pub idle_table_pointer_present:Option<bool>,pub queue_append_succeeds:Option<bool>,pub frozen_external_state:Option<bool>,pub scheduler_sample_ms:Option<u32>}
