#[derive(Clone)]pub(crate) struct ContinueInputs{pub callback:Inputs,pub ordinary_path_reached:Option<bool>,pub actor_counter50:Option<u8>,pub idle_queue_append_succeeds:Option<bool>,pub idle_table_pointer_present:Option<bool>,pub post_frame_event_bit:Option<bool>}
pub(crate) struct RemoveInputs{pub sector_unload_reached:Option<bool>,pub registry_actor_matches:Option<bool>,pub sector_id_range_contains_actor:Option<bool>,pub no_opcode11:Option<bool>,pub extra_draw_pointers_absent:Option<bool>,pub actor_global_pointers_differ:Option<bool>}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub(crate) struct Continuation{pub frame:usize,pub due_ms:u32,pub dispatch_ms:u32,pub sampled_ms:u32,pub expected_ms:u32,pub next_due_ms:u32,pub ended:bool,pub opcode32:bool}
struct Identity{owner:Binding,plan:NativeAssetPlan,retired:AtomicBool}
pub(crate) struct Frame{identity:Arc<Identity>,canvas:Canvas,pub dispatch_ms:u32,pub scheduler_ms:u32,pub next_due_ms:u32,pub frame:usize,pub fragments:usize}
pub(crate) struct Model<'a>{identity:Arc<Identity>,assets:&'a NativeStaticAssets,effect:&'a NativeActionSnapshot,record:NativeEffectRecord,tiles:BTreeMap<(u16,u8),PreparedTile>,draws:Vec<(NativeDrawCell,Option<u8>,(u16,u8))>,object:u32,class:u32,pending:Option<u32>,future:Option<u32>,stopped:bool,current:usize,expected:Option<u32>,queued_repeat:bool,continuations:usize,limit:usize}
impl Identity{fn active(&self,b:&Binding,now:i64)->Result<()>{ensure!(!self.retired.load(Ordering::Acquire)&&self.owner==*b&&now>=b.observed&&(b.cutoff==-1||now<b.cutoff),"Layer8 retired/full owner/revision/cutoff mismatch");Ok(())}}
impl Frame{pub fn view<'a>(&'a self,model:&Model<'_>,b:&Binding,now:i64)->Result<&'a Canvas>{self.identity.active(b,now)?;ensure!(Arc::ptr_eq(&self.identity,&model.identity)&&self.identity.plan==*model.assets.verified_plan(),"Foreign Layer8 private study identity/source plan");Ok(&self.canvas)}}
impl<'a> Model<'a>{
 pub fn new(enabled:bool,b:&Binding,expected:&Binding,now:i64,assets:&'a NativeStaticAssets,plan:&NativeAssetPlan,effect:&'a NativeActionSnapshot,index:usize,input:&CreateInputs)->Result<Self>{
  ensure!(enabled&&b==expected&&now>=b.observed&&(b.cutoff==-1||now<b.cutoff)&&assets.verified_plan()==plan&&effect.scene_plan()==plan&&plan.map_id==564&&effect.scene_sprite_id()==38&&effect.scene_firepot_creation_facts()&&effect.duration_ms()?==vec![83;11],"Layer8 disabled/full owner/verified actual FirePot facts mismatch");
  ensure!(input.loader_branch_reached==Some(true)&&input.existing_actor_absent==Some(true)&&input.allocation_succeeded==Some(true)&&input.render_player_pointer_equal==Some(false)&&input.initial_queue_count==Some(0)&&input.idle_table_pointer_present==Some(true)&&input.queue_append_succeeds==Some(true)&&input.frozen_external_state==Some(true),"Unknown Layer8 create/queue/pointer/global branch");
  let record=*assets.effect_records().get(index).context("Selected Layer8 source index absent")?;ensure!(record.effect.sprite_id==38&&record.effect.extended.is_none()&&assets.geometry().contains(WorldCell{x:i32::from(record.effect.x),y:i32::from(record.effect.y)}),"Actual nonextended FirePot38 record/absolute position required");
  let object=input.runtime_id_base.context("Original62F328 runtime ID base unknown")?.checked_add(u32::try_from(index)?).context("Layer8 ID overflow")?;let class=input.catalog_global_offset.context("Original647E90 Native catalog offset unknown")?.checked_add(38).context("Layer8 class overflow")?;
  ensure!(object>0&&object!=input.player_object_global.context("Original player object global unknown")?&&class<=i16::MAX as u32,"Only explicit nonplayer/signed-class source branch qualified");let sampled=input.scheduler_sample_ms.context("Creation fresh schedule clock unknown")?;let due=sampled.checked_add(584).context("Layer8 creation clock wraps")?;
  let tiles=assets.scene_tiles().iter().map(|(key,t)|Ok((*key,PreparedTile::new(t.clone())?))).collect::<Result<BTreeMap<_,_>>>()?;let draws=assets.scene_terrain()?;
  Ok(Self{identity:Arc::new(Identity{owner:b.clone(),plan:plan.clone(),retired:AtomicBool::new(false)}),assets,effect,record,tiles,draws,object,class,pending:Some(due),future:None,stopped:false,current:0,expected:None,queued_repeat:false,continuations:0,limit:11})
 }
 pub fn conditional_ids(&self)->(u32,u32){(self.object,self.class)}
 pub fn initial_due(&self,b:&Binding,now:i64)->Result<u32>{self.identity.active(b,now)?;ensure!(!self.stopped,"Only one Layer8 callback qualified");self.pending.context("Layer8 initial opcode32 absent")}
 pub fn preview(&self,b:&Binding,now:i64,input:&Inputs)->Result<(u32,u32,u32)>{self.preview_policy(b,now,input,true)}
 fn preview_policy(&self,b:&Binding,now:i64,input:&Inputs,static_roofs:bool)->Result<(u32,u32,u32)>{
  let due=self.initial_due(b,now)?;
  ensure!(input.timer_removed_before_callback==Some(true)&&input.callback_actor_matches==Some(true)&&input.queue_before_pop==Some(1)&&input.queue_after_pop==Some(0)&&input.actor_68_absent==Some(true)&&input.prior_draw_unlinked==Some(true)&&input.actor_globals_match==Some(false)&&input.neutral_clock_modifiers==Some(true),"Layer8 callback owner/pop/unlink/global/clock state unknown");
  ensure!(input.draw_branch_reached==Some(true)&&input.shadow_pointer_absent==Some(true)&&input.layer105_count==Some(0)&&input.body_pointer_present==Some(true)&&input.screen_floor_reference==Some(true)&&input.static_source_roofs==Some(static_roofs)&&input.terrain_first==Some(true),"Layer8 attr8 draw pointers/reference/roof/insertion unknown");
  let dispatch=input.dispatch_ms.context("Layer8 callback clock unknown")?;let sampled=input.scheduler_sample_ms.context("Layer8 callback fresh schedule clock unknown")?;ensure!(dispatch>=due&&sampled>=dispatch,"Layer8 early/nonmonotonic clock");let next=sampled.checked_add(85).context("Layer8 first frame clock wraps")?;Ok((dispatch,sampled,next))
 }
 fn paint_index(&self,blend:Option<Blend>,index:usize)->Result<Canvas>{let cell=WorldCell{x:i32::from(self.record.effect.x),y:i32::from(self.record.effect.y)};let view=ViewProjection{anchor_cell:cell,anchor_pixel:PixelPoint{x:256,y:250}};let mut canvas=Canvas::new(512,384)?;let mut raster=Raster::new(view,&canvas);for(anchor,depth,key)in &self.draws{raster.tile_roof(*anchor,*depth,&self.tiles[key],Shade::Native)?;}if let Some(blend)=blend{raster.sprite(NativeDrawCell::from_world(cell).context("Layer8 half-cell overflow")?,self.effect.scene_frame(index)?,0,blend)?;}raster.paint(&mut canvas,&self.identity.retired,0)?;Ok(canvas)}
 fn paint(&self,blend:Option<Blend>)->Result<Canvas>{self.paint_index(blend,1)}
 #[cfg(test)]pub fn comparison(&self,b:&Binding,now:i64,blend:Option<Blend>)->Result<Canvas>{self.identity.active(b,now)?;self.paint(blend)}
 pub fn sample(&mut self,b:&Binding,now:i64,input:&Inputs)->Result<Frame>{let(dispatch,sampled,next)=self.preview(b,now,input)?;let fragments=self.effect.scene_frame(1)?.fragments.as_ref().context("Actual Layer8 source fragments absent")?.references.len();let canvas=self.paint(Some(Blend::Screen))?;self.identity.active(b,now)?;self.pending=None;self.future=Some(next);self.stopped=true;self.current=1;self.expected=Some(next);Ok(Frame{identity:self.identity.clone(),canvas,dispatch_ms:dispatch,scheduler_ms:sampled,next_due_ms:next,frame:1,fragments})}
 pub fn continuation_preview(&self,b:&Binding,now:i64,input:&ContinueInputs)->Result<Continuation>{self.continuation_policy(b,now,input,true)}
 fn continuation_policy(&self,b:&Binding,now:i64,input:&ContinueInputs,static_roofs:bool)->Result<Continuation>{
  self.identity.active(b,now)?;ensure!(self.stopped&&self.continuations<self.limit,"First callback required; finite source repeat budget exhausted");let due=self.future.context("No owned Layer8 continuation")?;let q=&input.callback;
  ensure!(q.timer_removed_before_callback==Some(true)&&q.callback_actor_matches==Some(true)&&q.actor_68_absent==Some(true)&&q.prior_draw_unlinked==Some(true)&&q.actor_globals_match==Some(false)&&q.neutral_clock_modifiers==Some(true)&&q.draw_branch_reached==Some(true)&&q.shadow_pointer_absent==Some(true)&&q.layer105_count==Some(0)&&q.body_pointer_present==Some(true)&&q.screen_floor_reference==Some(true)&&q.static_source_roofs==Some(static_roofs)&&q.terrain_first==Some(true),"Continuation owner/global/neutral clock/draw branches unknown");
  ensure!(input.ordinary_path_reached==Some(true)&&input.actor_counter50==Some(0)&&input.post_frame_event_bit==Some(false)&&q.queue_before_pop==Some(usize::from(self.queued_repeat))&&q.queue_after_pop==Some(0),"Unknown ordinary path/end counter/event/queue state");
  let dispatch=q.dispatch_ms.context("Continuation dispatch unknown")?;let sampled=q.scheduler_sample_ms.context("Continuation internal clock unknown")?;ensure!(dispatch>=due&&sampled>=dispatch,"Early/backward Layer8 continuation");let expected=self.expected.context("Expected actor clock unknown")?;
  let frame=if self.queued_repeat{1}else if self.current==10{0}else{self.current+1};let ended=!self.queued_repeat&&frame==0;
  let(next,expected_next)=if ended{ensure!(input.idle_queue_append_succeeds==Some(true)&&input.idle_table_pointer_present==Some(true),"End idle queue allocation/table unknown");(sampled.checked_add(83).context("Repeat clock wraps")?,expected)}else if self.queued_repeat{let next=sampled.checked_add(85).context("Repeat first clock wraps")?;(next,next)}else{let late=sampled.checked_sub(expected).context("Clock before expected deadline")?;ensure!(late<=i32::MAX as u32,"Signed clock delta unqualified");(sampled.checked_add(83u32.saturating_sub(late).max(1)+2).context("Ordinary schedule wraps")?,expected.checked_add(85).context("Expected clock wraps")?)};
  self.effect.scene_frame(frame)?;Ok(Continuation{frame,due_ms:due,dispatch_ms:dispatch,sampled_ms:sampled,expected_ms:expected_next,next_due_ms:next,ended,opcode32:self.queued_repeat})
 }
 pub fn continue_sample(&mut self,b:&Binding,now:i64,input:&ContinueInputs)->Result<(Continuation,Frame)>{let step=self.continuation_preview(b,now,input)?;let canvas=self.paint_index(Some(Blend::Screen),step.frame)?;let fragments=self.effect.scene_frame(step.frame)?.fragments.as_ref().context("Layer8 fragments absent")?.references.len();self.current=step.frame;self.expected=Some(step.expected_ms);self.future=Some(step.next_due_ms);self.queued_repeat=step.ended;self.continuations+=1;Ok((step,Frame{identity:self.identity.clone(),canvas,dispatch_ms:step.dispatch_ms,scheduler_ms:step.sampled_ms,next_due_ms:step.next_due_ms,frame:step.frame,fragments}))}
 pub fn remove_from_sector(&mut self,b:&Binding,now:i64,input:&RemoveInputs)->Result<()>{self.identity.active(b,now)?;ensure!(input.sector_unload_reached==Some(true)&&input.registry_actor_matches==Some(true)&&input.sector_id_range_contains_actor==Some(true)&&input.no_opcode11==Some(true)&&input.extra_draw_pointers_absent==Some(true)&&input.actor_global_pointers_differ==Some(true)&&self.class!=0x68&&self.class!=0x8b7,"Sector/registry/immediate-removal branch unknown");self.retire();Ok(())}
 pub fn future_due(&self,b:&Binding,now:i64)->Result<u32>{self.identity.active(b,now)?;self.future.context("Layer8 future continuation not scheduled")}
 pub fn retire(&mut self){self.identity.retired.store(true,Ordering::Release);self.pending=None;self.future=None;self.stopped=true;}
}
impl Drop for Model<'_>{fn drop(&mut self){self.retire();}}

